% MAKE_REFERENCE  Run kalman_update.m on test_vectors.csv and write the
% posterior estimates to reference_output.csv at full double precision.
% Works in MATLAB (R2016b+) and GNU Octave (7+).

model = jsondecode(fileread('model.json'));
model.x0 = model.x0(:);   % ensure n-by-1

Z = dlmread('test_vectors.csv', ',', 1, 0);
X = kalman_update(Z, model);

fid = fopen('reference_output.csv', 'w');
fprintf(fid, 'x,y,vx,vy\n');
fprintf(fid, '%.17g,%.17g,%.17g,%.17g\n', X');
fclose(fid);
fprintf('wrote %d rows to reference_output.csv\n', size(X, 1));
